source='''def transform(grid):
    out = [row[:] for row in grid]
    patterns = []
    for cs in (2, 7, 12, 17):
        patterns.append(tuple(tuple(grid[r][cs:cs+3]) for r in range(1, 4)))
    boxes = []
    for rs in (8, 13, 18, 23):
        for cs in (2, 7, 12, 17):
