            if pattern in patterns:
                boxes.append((rs-1, rs+3, cs-1, cs+4))
                for r in range(rs-1, rs+4):
                    for c in range(cs-1, cs+4):
                        if out[r][c] == 8:
                            out[r][c] = 3
    # Four-connected boxes form either one line (green) or separate groups (red).
    remaining = set(range(len(boxes)))
    groups = 0
    while remaining:
        groups += 1
        stack = [remaining.pop()]
        while stack:
            i = stack.pop()
            a, b, c, d = boxes[i]
            touching = {j for j in remaining if not (boxes[j][1] < a or boxes[j][0] > b or boxes[j][3] < c or boxes[j][2] > d)}
            remaining -= touching
            stack.extend(touching)
    fill = 3 if groups == 1 else 2
    if fill == 3:
        for r in range(5):
            for c in range(22):
                if out[r][c] == 8:
                    out[r][c] = 3
    for r in (28, 29):
        for c in range(22):
            if out[r][c] == 8:
                out[r][c] = fill
    return out
